{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "label",
      "type": "string",
      "description": "Label text.",
      "required": true
    },
    {
      "name": "isLabelHidden",
      "type": "boolean",
      "description": "Visually hide the label.",
      "default": "false"
    },
    {
      "name": "description",
      "type": "string",
      "description": "Helper text displayed below the label."
    },
    {
      "name": "isOptional",
      "type": "boolean",
      "description": "Show an \"(optional)\" indicator next to the label.",
      "default": "false"
    },
    {
      "name": "isRequired",
      "type": "boolean",
      "description": "Mark the field as required.",
      "default": "false"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Disable the input and calendar. The field stays focusable and exposes `aria-disabled`; typing and opening are blocked.",
      "default": "false"
    },
    {
      "name": "disabledMessage",
      "type": "string",
      "description": "Explains why the input is disabled. With isDisabled, shows a tooltip on hover/keyboard focus (activation stays blocked). Use this instead of wrapping a disabled DateInput in Tooltip."
    },
    {
      "name": "value",
      "type": "ISODateString",
      "description": "Selected date in YYYY-MM-DD format."
    },
    {
      "name": "onChange",
      "type": "(value: ISODateString | undefined) => void",
      "description": "Callback invoked when the selected date changes."
    },
    {
      "name": "changeAction",
      "type": "(value: ISODateString | undefined) => void | Promise<void>",
      "description": "Async action fired after onChange. Drives optimistic UI updates via useTransition."
    },
    {
      "name": "isLoading",
      "type": "boolean",
      "description": "Whether the input is in a loading state. The field stays focusable and exposes `aria-busy` with a spinner; typing, picking, and clearing are blocked until loading ends.",
      "default": "false"
    },
    {
      "name": "min",
      "type": "ISODateString",
      "description": "Minimum selectable date (YYYY-MM-DD)."
    },
    {
      "name": "max",
      "type": "ISODateString",
      "description": "Maximum selectable date (YYYY-MM-DD)."
    },
    {
      "name": "dateConstraints",
      "type": "ReadonlyArray<(date: Date) => boolean>",
      "description": "Array of custom constraint functions that disable specific dates."
    },
    {
      "name": "placeholder",
      "type": "string",
      "description": "Placeholder text shown in the text input. A caller placeholder replaces the calendar format hint.",
      "default": "'Select a date'"
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "description": "Size of the input control.",
      "default": "'md'"
    },
    {
      "name": "status",
      "type": "{type: 'warning' | 'error' | 'success', message?: string}",
      "description": "Status indicator object for error, warning, or success states with a message."
    },
    {
      "name": "statusVariant",
      "type": "'attached' | 'detached' | 'tooltip'",
      "description": "How the status message is placed relative to the input. attached overlaps directly below the input (bordered treatment); detached floats below as a separate element with spacing; tooltip hides the message box and surfaces it in a tooltip on the status icon.",
      "default": "'attached'"
    },
    {
      "name": "labelTooltip",
      "type": "string",
      "description": "Tooltip text displayed via an info icon at the end of the label."
    },
    {
      "name": "hasClear",
      "type": "boolean",
      "description": "Shows a clear (×) button when a date value is set. Clicking it clears the value and returns focus to the input.",
      "default": "false"
    },
    {
      "name": "numberOfMonths",
      "type": "1 | 2",
      "description": "Number of months displayed simultaneously in the calendar popover.",
      "default": "1"
    },
    {
      "name": "weekStartsOn",
      "type": "0 | 1 | 2 | 3 | 4 | 5 | 6 | 'sun' | 'mon' | 'tue' | 'wed' | 'thu' | 'fri' | 'sat'",
      "description": "First day of week in Astryx calendar surfaces. A number (0 = Sunday to 6 = Saturday) or a three-letter day name; native pickers remain browser/OS-owned.",
      "default": "0"
    },
    {
      "name": "format",
      "type": "'date' | 'date_long' | 'date_weekday' | 'system_date' | ((value: ISODateString) => string)",
      "description": "How the committed date value is displayed. Named values are reused from Timestamp's format vocabulary: 'date' shows 'Mar 21, 2026', 'date_long' shows 'March 21, 2026', 'date_weekday' shows 'Wed, Mar 21, 2026', 'system_date' shows '2026-03-21'. 'date', 'date_long', and 'date_weekday' write the date in the field's calendar; 'system_date' stays the Gregorian ISO date. A function receives the ISO value and returns a custom string; the field cannot re-commit text it cannot read back. Applies only to the committed value, never to text being typed.",
      "default": "'date_long'"
    },
    {
      "name": "calendar",
      "type": "'gregory' | 'iso8601' | 'buddhist' | 'roc' | 'japanese' | 'persian' | 'indian' | 'hebrew' | 'chinese' | 'dangi' | 'coptic' | 'ethiopic' | 'ethioaa' | 'islamic-civil' | 'islamic-tbla' | 'islamic-umalqura'",
      "description": "The calendar the text field reads and writes dates in, and the calendar its popover and bottom sheet show. value, onChange, min, and max stay Gregorian ISO dates. People type a date the way the locale writes it in this calendar, in any decimal digits; the field reports a date only once it is complete, and names a date the calendar does not have. Years are years of this calendar: a Buddhist field reads 2026 as Buddhist year 2026, so set min and max on Buddhist and Minguo calendar fields to catch a Gregorian year typed by mistake. Calendars other than gregory, iso8601, buddhist, roc, and japanese need Temporal, native or a polyfill the application loads; without it the field shows Gregorian dates. With a calendar other than gregory or iso8601, a presentation that would show the native date control shows the popover on a fine pointer and the bottom sheet on a coarse pointer, because the native control is Gregorian; the bottom sheet shows the months, leap months, and era years of the calendar. A year in which the era changes is labeled with the era of the shown month, such as 平成31 in January 2019 and 令和元 in July.",
      "default": "the InternationalizationProvider's calendar, else 'gregory'"
    },
    {
      "name": "presentation",
      "type": "'popover' | 'bottom-sheet' | 'native' | 'adaptive-bottom-sheet' | 'adaptive-native'",
      "description": "Which surface draws the date picker. 'adaptive-native' (the default) uses Astryx's calendar popover on a fine pointer and the browser/OS picker (input type=date) on a coarse pointer, keeping Astryx fallbacks where a native control cannot express the value; 'native' always uses the browser/OS picker with no fallback; 'adaptive-bottom-sheet' uses the popover on a fine pointer and Astryx's bottom-sheet picker on a coarse pointer; 'popover' and 'bottom-sheet' force that Astryx surface on every pointer. Every value opens a picker; a typed-only field is TimeInput's alone. Use a non-native presentation for a field that needs weekStartsOn, numberOfMonths or dateConstraints, none of which a native picker can express. With a calendar other than gregory or iso8601, 'native' and 'adaptive-native' use the popover on a fine pointer and the bottom sheet on a coarse pointer, and an explicit 'native' warns in development.",
      "default": "'adaptive-native'"
    },
    {
      "name": "nativePicker",
      "type": "'touch' | 'always' | 'never'",
      "description": "Deprecated: use presentation ('touch' = 'adaptive-native', 'always' = 'native', 'never' = 'adaptive-bottom-sheet'). Still works exactly as released; presentation wins when both are set. With a calendar other than gregory or iso8601, 'touch' and 'always' use the popover on a fine pointer and the bottom sheet on a coarse pointer.",
      "default": "'touch'"
    },
    {
      "name": "width",
      "type": "SizeValue",
      "description": "Width of the field (number = pixels, string used as-is, e.g. \"100%\"). Sizes the whole field (label, control, and status) so they stay aligned."
    },
    {
      "name": "containerXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the Field box around the label, control, and status. containerClassName and containerStyle take a class name and inline styles for the same box. No effect (development warning) where no Field box renders: inside InputGroup (style the group) and in a horizontal-labels FormLayout."
    },
    {
      "name": "containerClassName",
      "type": "string",
      "description": "Class name for the Field box. Same targeting as containerXstyle."
    },
    {
      "name": "containerStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the Field box. Same targeting as containerXstyle."
    },
    {
      "name": "controlXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the visual control box: the bordered element that holds the text, icons, and end controls, never the native input. controlClassName and controlStyle take a class name and inline styles for the same box. Replaces root xstyle, className, and style, which this component does not accept."
    },
    {
      "name": "controlClassName",
      "type": "string",
      "description": "Class name for the visual control box. Same targeting as controlXstyle."
    },
    {
      "name": "controlStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the visual control box. Same targeting as controlXstyle."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
